package com.vibeguard.samples.flags; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Protects operational feature-flag changes with an administrator key. */ @RestController @RequestMapping("/internal/flags") public class FlagController { private final Map<String,Flag> flags=new ConcurrentHashMap<>(); @Value("${FEATURE_FLAGS_ADMIN_KEY:}") private String key; @PostMapping public ResponseEntity<Flag> create(@RequestHeader("X-Feature-Flags-Key") String supplied,@Valid @RequestBody Request request){if(!key.equals(supplied))return ResponseEntity.status(401).build();Flag flag=new Flag(request.name(),false);flags.put(flag.name(),flag);return ResponseEntity.status(201).body(flag);}@PostMapping("/{name}/toggle") public ResponseEntity<Flag> toggle(@RequestHeader("X-Feature-Flags-Key") String supplied,@PathVariable String name){if(!key.equals(supplied))return ResponseEntity.status(401).build();Flag flag=flags.get(name);if(flag==null)return ResponseEntity.notFound().build();Flag changed=new Flag(name,!flag.enabled());flags.put(name,changed);return ResponseEntity.ok(changed);}@GetMapping public ResponseEntity<Collection<Flag>> list(@RequestHeader("X-Feature-Flags-Key") String supplied){return key.equals(supplied)?ResponseEntity.ok(flags.values()):ResponseEntity.status(401).build();}record Request(@NotBlank String name){}record Flag(String name,boolean enabled){} }
